<?php
require 'config.php'; wajib_login(); if(!role('admin')){header('Location: dashboard.php');exit;}
$msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $pid=(int)$_POST['id_pengepul'];$sid=(int)$_POST['id_sampah'];$berat=(float)$_POST['berat_kg'];$harga=(float)$_POST['harga_per_kg']; $q=$conn->prepare('SELECT stok_kg FROM sampah WHERE id_sampah=?');$q->bind_param('i',$sid);$q->execute();$st=$q->get_result()->fetch_assoc(); if(!$st||$berat<=0||$harga<=0)$msg='Data penjualan tidak valid.';elseif($berat>$st['stok_kg'])$msg='Stok sampah tidak mencukupi.';else{$total=$berat*$harga;$aid=$_SESSION['user']['id_user'];$q=$conn->prepare("INSERT INTO penjualan_pengepul(id_admin,id_pengepul,id_sampah,berat_kg,harga_per_kg,total_rp,status) VALUES(?,?,?,?,?,?,'pending')");$q->bind_param('iiiddd',$aid,$pid,$sid,$berat,$harga,$total);$q->execute();$msg='Penawaran berhasil dikirim ke pengepul.';}} $users=$conn->query("SELECT id_user,nama FROM user WHERE role='pengepul' ORDER BY nama");$sampah=$conn->query('SELECT * FROM sampah ORDER BY jenis_sampah');
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jual ke Pengepul</title><link rel="stylesheet" href="style.css"></head><body><?php include 'nav.php'; ?><main class="container"><div class="panel narrow"><h1>Jual Sampah ke Pengepul</h1><?php if($msg): ?><div class="alert"><?=e($msg)?></div><?php endif; ?><form method="post"><label>Pengepul</label><select name="id_pengepul" required><?php while($u=$users->fetch_assoc()): ?><option value="<?=$u['id_user']?>"><?=e($u['nama'])?></option><?php endwhile; ?></select><label>Jenis Sampah</label><select name="id_sampah" required><?php while($x=$sampah->fetch_assoc()): ?><option value="<?=$x['id_sampah']?>"><?=e($x['jenis_sampah'])?> - stok <?=number_format($x['stok_kg'],2,',','.')?> kg</option><?php endwhile; ?></select><label>Berat (kg)</label><input type="number" step="0.01" min="0.01" name="berat_kg" required><label>Harga jual / kg</label><input type="number" step="100" min="1" name="harga_per_kg" required><button class="btn primary full">Kirim Penawaran</button></form></div></main></body></html>